const Default = () => {
    const table = useReactTable({
      data: mockData,
      columns,
      getCoreRowModel: getCoreRowModel(),
      columnResizeMode: "onChange",
      columnResizeDirection: "ltr",
    });

    return <BaseTable table={table} />;
};

const WithSorting = () => {
    const [sorting, setSorting] = useState<SortingState>([]);

    const table = useReactTable({
      data: mockData,
      columns,
      getCoreRowModel: getCoreRowModel(),
      getSortedRowModel: getSortedRowModel(),
      state: {
        sorting,
      },
      enableSorting: true,
      onSortingChange: setSorting,
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable
                headerMenuFeatureFlags={{
                  showSortingItems: true,
                }}
                table={table} />
        </div>
    );
};

const WithColumnPinning = () => {
    const [columnPinning, setColumnPinning] = useState<ColumnPinningState>({
      left: [],
      right: [],
    });

    const table = useReactTable({
      data: mockData,
      columns,
      getCoreRowModel: getCoreRowModel(),
      state: {
        columnPinning,
      },
      enableColumnResizing: false,
      onColumnPinningChange: setColumnPinning,
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable
                headerMenuFeatureFlags={{
                  showPinningItems: true,
                }}
                table={table} />
        </div>
    );
};

const WithColumnResizing = () => {
    const [columnSizing, setColumnSizing] = useState<ColumnSizingState>({});

    const table = useReactTable({
      data: mockData,
      columns,
      getCoreRowModel: getCoreRowModel(),
      state: {
        columnSizing,
      },
      columnResizeMode: "onChange",
      columnResizeDirection: "ltr",
      onColumnSizingChange: setColumnSizing,
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable
                headerMenuFeatureFlags={{
                  showResizeItem: true,
                }}
                table={table} />
        </div>
    );
};

const WithColumnConfig = () => {
    const [columnVisibility, setColumnVisibility] = useState<VisibilityState>(
      columns.reduce((acc, col) => {
        return {
          ...acc,
          [col.accessorKey]: true,
        };
      }, {}),
    );

    const table = useReactTable({
      data: mockData,
      columns,
      getCoreRowModel: getCoreRowModel(),
      getSortedRowModel: getSortedRowModel(),
      state: {
        columnVisibility,
      },
      onColumnVisibilityChange: setColumnVisibility,
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable
                headerMenuFeatureFlags={{
                  showConfigItem: true,
                }}
                table={table} />
        </div>
    );
};

const LoadingState = () => {
    const table = useReactTable({
      data: [] as Person[],
      columns,
      getCoreRowModel: getCoreRowModel(),
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable isLoading table={table} />
        </div>
    );
};

const EmptyState = () => {
    const table = useReactTable({
      data: [] as Person[],
      columns,
      getCoreRowModel: getCoreRowModel(),
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable table={table} />
        </div>
    );
};

const ErrorState = () => {
    const table = useReactTable({
      data: [] as Person[],
      columns,
      getCoreRowModel: getCoreRowModel(),
    });

    return (
        <div style={{ height: "400px" }}>
            <BaseTable error={new Error("Example error")} table={table} />
        </div>
    );
};

