const Default = () => {
  const objectSet = useEmployeeObjectSet();
  const filterDefinitions = useMemo(
    (): FilterDefinitionUnion<Employee>[] => [
      departmentFilter,
      locationCityFilter,
    ],
    [],
  );
  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={filterDefinitions}
      />
    </div>
  );
};

const WithAllFilterTypes = () => {
  const objectSet = useEmployeeObjectSet();
  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={sharedFilterDefinitions}
      />
    </div>
  );
};

const WithTitleAndIcon = () => {
  const objectSet = useEmployeeObjectSet();
  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={sharedFilterDefinitions}
        title="Employee Filters"
        titleIcon={FILTER_ICON}
      />
    </div>
  );
};

const WithActiveFilterCount = () => {
  const objectSet = useEmployeeObjectSet();
  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={sharedFilterDefinitions}
        showActiveFilterCount={true}
      />
    </div>
  );
};

const WithSorting = () => {
  const objectSet = useEmployeeObjectSet();
  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={sharedFilterDefinitions}
        enableSorting={true}
      />
    </div>
  );
};

const KeywordSearch = () => {
  const objectSet = useEmployeeObjectSet();
  const filterDefinitions = useMemo(
    (): FilterDefinitionUnion<Employee>[] => [
      {
        type: "KEYWORD_SEARCH",
        properties: ["fullName", "department", "jobTitle", "locationCity"],
        label: "Search",
      } as FilterDefinitionUnion<Employee>,
      departmentFilter,
      locationCityFilter,
    ],
    [],
  );

  return (
    <div style={SIDEBAR_STYLE}>
      <FilterList
        objectSet={objectSet}
        filterDefinitions={filterDefinitions}
      />
    </div>
  );
};

